<?php require_once __DIR__ . '/../../config/config.php'; header('Content-Type: application/json; charset=utf-8'); $u=auth_user(); if(!$u) json_err('unauthorized',401); $pdo=db(); $pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION); $b=json_decode(file_get_contents('php://input'),true); $oid=(int)($b['order_id']??0); $rm=(int)($b['real_month']??0); $ry=(int)($b['real_year']??0); if($oid<=0||$rm<1||$rm>12||$ry<2000) json_err('invalid_params',422); $st=$pdo->prepare('UPDATE orders SET real_month=?, real_year=? WHERE id=?'); $st->execute([$rm,$ry,$oid]); json_ok(['ok'=>true]);